let assignmentDraft=null,assignmentRecords=[];
const beforeAssignmentPackages=render;
render=function(){if(location.hash!=='#assignment-packages')return beforeAssignmentPackages();document.getElementById('app').innerHTML=integratedShell('assignment-packages',heading('Assignment package studio','Scholarion Academy · Seven assessment formats')+`<section class="card prose"><strong>AI DRAFT — requires SME and instructional-designer approval.</strong><p>Author structured packages, check alignment and export editions. Templates are not generated lessons or executed notebooks.</p><p id="ap-status" role="status">Connecting…</p><label>Authorized course<select id="ap-course"></select></label><label>Assignment format<select id="ap-kind">${[['lab','Lab'],['exercises','Practice exercises'],['activity','In-class activity'],['quiz','Scenario quiz'],['mini_project','Mini-project'],['scenario_project','Scenario project'],['capstone','Senior capstone']].map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><button class="button" id="ap-new">Create local template</button><a href="#curriculum-review">Full course validation</a> · <a href="#program-studio">Program studio</a></section><div id="ap-library"></div><section class="card prose"><h2>Package editor</h2><label>Structured package JSON<textarea id="ap-json" rows="24" spellcheck="false" aria-describedby="ap-edit-help"></textarea></label><p id="ap-edit-help">Fill placement, five competencies, Bloom-mapped outcomes, four pillars and all format sections. Keep answers under instructor; text still needs educator review before student use.</p><button class="button" id="ap-save">Save revision and validate</button> <button class="button secondary" data-ap-export="student">Export saved student edition</button> <button class="button secondary" data-ap-export="instructor">Export saved instructor edition</button><div id="ap-findings" role="status"></div></section>`,model.role);bind();normalizeWorkspace();loadAssignmentPackages();};
async function loadAssignmentPackages(){try{workspaceSession=await workspaceApi('session');if(!workspaceSession.courses.includes(selectedCourse))selectedCourse=workspaceSession.courses[0]||'';const d=await workspaceApi('assignment-packages/list');if(location.hash!=='#assignment-packages')return;assignmentRecords=d.packages;document.getElementById('ap-course').innerHTML=workspaceSession.courses.map(c=>`<option ${c===selectedCourse?'selected':''}>${esc(c)}</option>`).join('');document.getElementById('ap-library').innerHTML=d.packages.map(p=>`<section class="card prose"><h3>${esc(p.package.context.topic||'Untitled '+p.package.kind)}</h3><p>Revision ${p.revision}</p><button class="button secondary" data-ap-open="${p.id}">Edit draft</button></section>`).join('');document.getElementById('ap-status').textContent=d.packages.length+' saved drafts. Publication disabled.';}catch(e){document.getElementById('ap-status').textContent=e.message+' — Authorized instructor session required.';}}
document.addEventListener('change',e=>{if(e.target.id==='ap-course'){selectedCourse=e.target.value;assignmentDraft=null;document.getElementById('ap-json').value='';document.getElementById('ap-findings').textContent='';loadAssignmentPackages();}});
document.addEventListener('click',async e=>{const b=e.target.closest('#ap-new,#ap-save,[data-ap-open],[data-ap-export]');if(!b)return;b.disabled=true;try{if(b.id==='ap-new'){assignmentDraft=null;const p=await workspaceApi('assignment-packages/template',{kind:document.getElementById('ap-kind').value});document.getElementById('ap-json').value=JSON.stringify(p,null,2);}else if(b.dataset.apOpen){assignmentDraft=assignmentRecords.find(p=>p.id===b.dataset.apOpen);document.getElementById('ap-json').value=JSON.stringify(assignmentDraft.package,null,2);}else if(b.id==='ap-save'){const p=JSON.parse(document.getElementById('ap-json').value),r=await workspaceApi('assignment-packages/save',{package:p,id:assignmentDraft?.id,revision:assignmentDraft?.revision||0});assignmentDraft={id:r.id,revision:r.revision,package:p};await loadAssignmentPackages();document.getElementById('ap-findings').innerHTML=`<h3>Saved revision ${r.revision}: ${r.findings.length} findings</h3><p>Publication remains blocked. Structural checks do not verify originality, correctness or accessibility.</p><ul>${r.findings.map(f=>`<li>${esc(f.path)}: ${esc(f.message)}</li>`).join('')}</ul>`;}else{if(!assignmentDraft)throw Error('Save or open a package first');const p=await workspaceApi('assignment-packages/export',{id:assignmentDraft.id,edition:b.dataset.apExport});download('assignment-'+b.dataset.apExport+'.json',JSON.stringify(p,null,2),'application/json');}}catch(err){document.getElementById('ap-status').textContent=err.message;}finally{b.disabled=false;}});
render();
